function safe(value) {
  if (value === null || value === undefined || value === "") {
    return "-";
  }
  return String(value);
}

function esc(value) {
  return safe(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function toNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function splitPeople(value) {
  return String(value || "")
    .split(/[、,，;；\s]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function getToday() {
  return new Date().toISOString().slice(0, 10);
}

function parseDeadline(deadline) {
  if (!deadline) {
    return null;
  }
  const text = String(deadline).trim();
  if (/^\d{4}-\d{2}$/.test(text)) {
    return new Date(`${text}-28`).getTime();
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return new Date(text).getTime();
  }
  return null;
}

function pickBadge(status) {
  if (status === "高风险") {
    return "badge badge-risk";
  }
  if (status === "需关注") {
    return "badge badge-watch";
  }
  if (status === "已完成") {
    return "badge badge-done";
  }
  return "badge badge-normal";
}

function makeDefaultMetrics() {
  return METRIC_DEFS.map((item) => ({
    key: item.key,
    name: item.name,
    target: 0,
    completed: 0,
    gap: 0,
    detail: ""
  }));
}

function normalizeMetrics(input) {
  const list = Array.isArray(input) ? input : [];
  return METRIC_DEFS.map((def) => {
    const found = list.find((item) => item && item.key === def.key) || list.find((item) => item && item.name === def.name);
    return {
      key: def.key,
      name: def.name,
      target: toNumber(found?.target),
      completed: toNumber(found?.completed),
      gap: toNumber(found?.gap),
      detail: String(found?.detail || "")
    };
  });
}

function normalizeProject(project) {
  const metrics = normalizeMetrics(project.metrics);
  const totalTarget = metrics.reduce((sum, item) => sum + (item.target > 0 ? item.target : 0), 0);
  const totalCompleted = metrics.reduce((sum, item) => sum + (item.completed > 0 ? item.completed : 0), 0);
  const computedRate = totalTarget > 0 ? Math.round((totalCompleted / totalTarget) * 100) : 0;
  const positiveGaps = metrics.filter((item) => item.gap > 0).map((item) => `${item.name}差${item.gap}`);
  const hasGap = positiveGaps.length > 0 || !!project.hasGap;
  const completionRate = Math.max(0, Math.min(100, project.completionRate ?? computedRate));
  const people = Array.isArray(project.people) ? project.people.filter(Boolean) : splitPeople(project.peopleText);
  const status = project.status || (project.workflowStatus === "done" ? "已完成" : hasGap ? "需关注" : "正常");
  const deadline = String(project.deadline || "");
  const overdue = Boolean(project.overdue) || (() => {
    const stamp = parseDeadline(deadline);
    if (!stamp || status === "已完成") {
      return false;
    }
    return stamp < new Date(`${getToday()}T00:00:00`).getTime();
  })();

  return {
    id: String(project.id || `USR-${Date.now()}`),
    sourceTable: String(project.sourceTable || "manual"),
    projectName: String(project.projectName || "未命名项目"),
    contractNo: String(project.contractNo || "待补充"),
    projectCode: String(project.projectCode || project.contractNo || ""),
    owner: String(project.owner || "待分配"),
    currentStage: String(project.currentStage || "推进中"),
    status,
    workflowStatus: String(project.workflowStatus || "in_progress"),
    dataStatus: String(project.dataStatus || "validated"),
    evidenceStatus: String(project.evidenceStatus || "partial"),
    completionRate,
    hasGap,
    gapSummary: String(project.gapSummary || (positiveGaps.length ? positiveGaps.join("；") : "暂无硬性缺口")),
    nextAction: String(project.nextAction || "按计划推进并在本周更新状态"),
    deadline,
    startDate: String(project.startDate || ""),
    period: String(project.period || ""),
    overdue,
    riskLevel: String(project.riskLevel || (status === "高风险" ? "high" : status === "需关注" ? "medium" : "low")),
    targetSummary: String(project.targetSummary || ""),
    budget: String(project.budget || ""),
    people,
    metrics,
    evidence: {
      report: String(project.evidence?.report || ""),
      ppt: String(project.evidence?.ppt || ""),
      support: String(project.evidence?.support || "")
    },
    notes: String(project.notes || "")
  };
}

function normalizeTodo(todo) {
  return {
    id: String(todo.id || `TODO-${Date.now()}`),
    title: String(todo.title || "未命名待办"),
    projectId: String(todo.projectId || ""),
    owner: String(todo.owner || "待分配"),
    priority: ["高", "中", "低"].includes(todo.priority) ? todo.priority : "中",
    dueDate: String(todo.dueDate || ""),
    status: todo.status === "done" ? "done" : "todo",
    remark: String(todo.remark || "")
  };
}

function normalizeData(data) {
  const projects = Array.isArray(data.projects) ? data.projects.map(normalizeProject) : [];
  const todos = Array.isArray(data.todos) ? data.todos.map(normalizeTodo) : [];

  return {
    version: String(data.version || "4.0.0"),
    generatedAt: String(data.generatedAt || ""),
    datasetName: String(data.datasetName || "云南项目执行看板"),
    sourceFiles: Array.isArray(data.sourceFiles) ? data.sourceFiles : [],
    projects,
    todos,
    dictionaries: data.dictionaries || {}
  };
}

function saveToLocal() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state.data));
}

function showToast(message) {
  els.toast.textContent = message;
  els.toast.classList.add("show");
  setTimeout(() => {
    els.toast.classList.remove("show");
  }, 1800);
}

function loadData(seed) {
  state.seedData = JSON.parse(JSON.stringify(seed));
  const localRaw = localStorage.getItem(STORAGE_KEY);

  if (localRaw) {
    try {
      const parsed = JSON.parse(localRaw);
      state.data = normalizeData(parsed);
      return;
    } catch {
      state.data = normalizeData(seed);
      saveToLocal();
      return;
    }
  }

  state.data = normalizeData(seed);
  saveToLocal();
}

function sortProjects(projects) {
  return [...projects].sort((a, b) => {
    const riskA = a.status === "高风险" ? 3 : a.status === "需关注" ? 2 : a.status === "已完成" ? 0 : 1;
    const riskB = b.status === "高风险" ? 3 : b.status === "需关注" ? 2 : b.status === "已完成" ? 0 : 1;
    if (riskA !== riskB) {
      return riskB - riskA;
    }
    return b.completionRate - a.completionRate;
  });
}

function applyFilters() {
  const keyword = state.filters.keyword.trim().toLowerCase();

  const list = state.data.projects.filter((project) => {
    const keywordOk = keyword
      ? [project.projectName, project.contractNo, project.owner, project.nextAction]
          .map((item) => String(item).toLowerCase())
          .some((text) => text.includes(keyword))
      : true;

    const ownerOk = state.filters.owner === "all" || project.owner === state.filters.owner;
    const statusOk = state.filters.status === "all" || project.status === state.filters.status;
    const overdueOk =
      state.filters.overdue === "all" ||
      (state.filters.overdue === "yes" ? project.overdue : !project.overdue);
    const gapOk =
      state.filters.gap === "all" ||
      (state.filters.gap === "yes" ? project.hasGap : !project.hasGap);

    return keywordOk && ownerOk && statusOk && overdueOk && gapOk;
  });

  state.filteredProjects = sortProjects(list);
  renderAll();
}

function fillSelect(select, options) {
  select.innerHTML = "";
  const allOption = document.createElement("option");
  allOption.value = "all";
  allOption.textContent = "全部";
  select.appendChild(allOption);

  options.forEach((item) => {
    const opt = document.createElement("option");
    opt.value = item;
    opt.textContent = item;
    select.appendChild(opt);
  });
}

function refreshFilterOptions() {
  const owners = [...new Set(state.data.projects.map((item) => item.owner).filter(Boolean))];
  const statuses = [...new Set(state.data.projects.map((item) => item.status).filter(Boolean))];
  fillSelect(els.ownerFilter, owners);
  fillSelect(els.statusFilter, statuses);

  els.ownerFilter.value = state.filters.owner;
  els.statusFilter.value = state.filters.status;
}

function renderTopCards() {
  const total = state.data.projects.length;
  const completed = state.data.projects.filter((item) => item.status === "已完成" || item.workflowStatus === "done").length;
  const highRisk = state.data.projects.filter((item) => item.status === "高风险" || (item.overdue && item.hasGap)).length;
  const todayTodo = state.data.todos.filter((item) => item.status !== "done" && item.dueDate === getToday()).length;

  els.topCards.innerHTML = `
    <article class="card">
      <p class="label">总项目数</p>
      <p class="value">${total}</p>
      <p class="sub">当前录入项目总量</p>
    </article>
    <article class="card">
      <p class="label">已完成项目数</p>
      <p class="value">${completed}</p>
      <p class="sub">状态为已完成或已收尾</p>
    </article>
    <article class="card">
      <p class="label">高风险项目数</p>
      <p class="value">${highRisk}</p>
      <p class="sub">逾期且有缺口也计入高风险</p>
    </article>
    <article class="card">
      <p class="label">今日待办数</p>
      <p class="value">${todayTodo}</p>
      <p class="sub">今天到期且未完成</p>
    </article>
  `;
}

function renderHomePanels() {
  const todayTodos = state.data.todos
    .filter((item) => item.status !== "done" && item.dueDate === getToday())
    .sort((a, b) => PRIORITY_ORDER[b.priority] - PRIORITY_ORDER[a.priority]);

  els.todayList.innerHTML =
    todayTodos.length > 0
      ? todayTodos.map((item) => `<li>${esc(item.title)}（${esc(item.owner)}）</li>`).join("")
      : "<li>今天没有硬性到期任务，可安排补证与复核。</li>";

  const riskyProjects = state.data.projects
    .filter((item) => item.status === "高风险" || (item.overdue && item.hasGap))
    .slice(0, 6);

  els.riskList.innerHTML =
    riskyProjects.length > 0
      ? riskyProjects.map((item) => `<li>${esc(item.projectName)}：${esc(item.nextAction)}</li>`).join("")
      : "<li>暂无高风险项目。</li>";

  const needMaterials = state.data.projects.filter((item) => {
    const evidence = item.evidence || {};
    const text = `${evidence.support || ""}${evidence.report || ""}${evidence.ppt || ""}`.trim();
    return item.evidenceStatus === "missing" || item.evidenceStatus === "partial" || !text;
  });

  els.materialList.innerHTML =
    needMaterials.length > 0
      ? needMaterials.slice(0, 6).map((item) => `<li>${esc(item.projectName)}（负责人：${esc(item.owner)}）</li>`).join("")
      : "<li>材料完整度较好，保持更新即可。</li>";

  const avg =
    state.data.projects.length > 0
      ? Math.round(state.data.projects.reduce((sum, item) => sum + item.completionRate, 0) / state.data.projects.length)
      : 0;
  els.overallRate.textContent = `${avg}%`;
  els.overallHint.textContent = `按全部项目的指标完成率均值计算，共 ${state.data.projects.length} 项。`;
}

function renderResultInfo() {
  els.resultInfo.textContent = `当前显示 ${state.filteredProjects.length} / ${state.data.projects.length} 个项目`;
}

function renderProjectTable() {
  if (!state.filteredProjects.length) {
    els.projectTableBody.innerHTML = '<tr><td colspan="10">没有符合条件的项目</td></tr>';
    return;
  }

  els.projectTableBody.innerHTML = state.filteredProjects
    .map((project) => {
      const deadlineText = project.overdue ? `${safe(project.deadline)}（已逾期）` : safe(project.deadline);
      return `
        <tr>
          <td class="project-name">${esc(project.projectName)}</td>
          <td>${esc(project.contractNo)}</td>
          <td>${esc(project.owner)}</td>
          <td>${esc(project.currentStage)}</td>
          <td class="progress">
            ${project.completionRate}%
            <div class="progress-bar"><div class="progress-fill" style="width:${project.completionRate}%;"></div></div>
          </td>
          <td>${esc(project.gapSummary)}</td>
          <td>${esc(project.nextAction)}</td>
          <td>${esc(deadlineText)}</td>
          <td><span class="${pickBadge(project.status)}">${esc(project.status)}</span></td>
          <td>
            <button class="btn" data-action="detail" data-id="${esc(project.id)}">详情</button>
            <button class="btn ghost" data-action="edit" data-id="${esc(project.id)}">编辑</button>
          </td>
        </tr>
      `;
    })
    .join("");
}

function renderProjectCards() {
  if (!state.filteredProjects.length) {
    els.projectCardList.innerHTML = "<p class='hint'>没有符合条件的项目</p>";
    return;
  }

  els.projectCardList.innerHTML = state.filteredProjects
    .map((project) => {
      return `
        <article class="project-item">
          <div class="item-head">
            <p class="item-title">${esc(project.projectName)}</p>
            <span class="${pickBadge(project.status)}">${esc(project.status)}</span>
          </div>
          <div class="item-grid">
            <p>合同编号：${esc(project.contractNo)}</p>
            <p>负责人：${esc(project.owner)}</p>
            <p>当前阶段：${esc(project.currentStage)}</p>
            <p>完成率：${esc(project.completionRate)}%</p>
            <p>缺口：${esc(project.gapSummary)}</p>
            <p>截止时间：${esc(project.deadline || "未填写")}${project.overdue ? "（已逾期）" : ""}</p>
          </div>
          <p class="hint">下一步：${esc(project.nextAction)}</p>
          <div class="item-actions">
            <button class="btn" data-action="detail" data-id="${esc(project.id)}">详情</button>
            <button class="btn ghost" data-action="edit" data-id="${esc(project.id)}">编辑</button>
          </div>
        </article>
      `;
    })
    .join("");
}

function sortTodos(todos) {
  return [...todos].sort((a, b) => {
    if (a.status !== b.status) {
      return a.status === "todo" ? -1 : 1;
    }
    const pDiff = PRIORITY_ORDER[b.priority] - PRIORITY_ORDER[a.priority];
    if (pDiff !== 0) {
      return pDiff;
    }
    return String(a.dueDate).localeCompare(String(b.dueDate));
  });
}

function renderTodoList() {
  const list = sortTodos(state.data.todos);
  els.todoList.innerHTML = list
    .map((todo) => {
      const checked = todo.status === "done" ? "checked" : "";
      const rowClass = todo.status === "done" ? "todo-row done" : "todo-row";
      return `
        <li class="${rowClass}">
          <input type="checkbox" data-todo-id="${esc(todo.id)}" ${checked} />
          <div class="todo-main">
            <p class="todo-title">${esc(todo.title)}</p>
            <p class="todo-meta">负责人：${esc(todo.owner)} | 优先级：${esc(todo.priority)} | 截止：${esc(todo.dueDate || "未填写")}${todo.projectId ? ` | 项目：${esc(todo.projectId)}` : ""}</p>
            ${todo.remark ? `<p class="todo-meta">备注：${esc(todo.remark)}</p>` : ""}
          </div>
        </li>
      `;
    })
    .join("");
}

function renderMetricEditor(metrics) {
  const rows = normalizeMetrics(metrics || makeDefaultMetrics());
  els.metricRows.innerHTML = rows
    .map((metric) => {
      return `
        <div class="metric-row" data-key="${esc(metric.key)}">
          <div class="metric-name">${esc(metric.name)}</div>
          <label>
            <span>目标</span>
            <input type="number" class="m-target" value="${esc(metric.target)}" min="0" />
          </label>
          <label>
            <span>完成</span>
            <input type="number" class="m-completed" value="${esc(metric.completed)}" min="0" />
          </label>
          <label>
            <span>缺口</span>
            <input type="number" class="m-gap" value="${esc(metric.gap)}" />
          </label>
          <label>
            <span>说明</span>
            <input type="text" class="m-detail" value="${esc(metric.detail)}" placeholder="可写人员、题目、佐证信息" />
          </label>
        </div>
      `;
    })
    .join("");
}

function collectMetricRows() {
  return Array.from(els.metricRows.querySelectorAll(".metric-row")).map((row) => {
    const key = row.dataset.key;
    const def = METRIC_DEFS.find((item) => item.key === key);
    return {
      key,
      name: def ? def.name : key,
      target: toNumber(row.querySelector(".m-target")?.value),
      completed: toNumber(row.querySelector(".m-completed")?.value),
      gap: toNumber(row.querySelector(".m-gap")?.value),
      detail: String(row.querySelector(".m-detail")?.value || "")
    };
  });
}

function clearProjectForm() {
  els.projectId.value = "";
  els.projectName.value = "";
  els.contractNo.value = "";
  els.projectOwner.value = "";
  els.currentStage.value = "推进中";
  els.projectStatus.value = "正常";
  els.deadline.value = "";
  els.gapSummary.value = "";
  els.nextAction.value = "";
  els.peopleText.value = "";
  els.targetSummary.value = "";
  els.supportEvidence.value = "";
  els.notes.value = "";
  renderMetricEditor(makeDefaultMetrics());
}

function fillProjectForm(projectId) {
  const project = state.data.projects.find((item) => item.id === projectId);
  if (!project) {
    return;
  }

  els.projectId.value = project.id;
  els.projectName.value = project.projectName;
  els.contractNo.value = project.contractNo;
  els.projectOwner.value = project.owner;
  els.currentStage.value = project.currentStage;
  els.projectStatus.value = project.status;
  els.deadline.value = project.deadline;
  els.gapSummary.value = project.gapSummary;
  els.nextAction.value = project.nextAction;
  els.peopleText.value = project.people.join("、");
  els.targetSummary.value = project.targetSummary;
  els.supportEvidence.value = [project.evidence.support, project.evidence.report, project.evidence.ppt]
    .filter(Boolean)
    .join("\n");
  els.notes.value = project.notes;
  renderMetricEditor(project.metrics);
  els.projectForm.scrollIntoView({ behavior: "smooth", block: "start" });
}

function renderDrawer() {
  const project = state.data.projects.find((item) => item.id === state.drawer.projectId);
  if (!project) {
    return;
  }

  els.drawerTitle.textContent = project.projectName;
  const tab = state.drawer.tab;

  if (tab === "basic") {
    els.drawerContent.innerHTML = `
      <dl class="kv">
        <dt>合同编号</dt><dd>${esc(project.contractNo)}</dd>
        <dt>负责人</dt><dd>${esc(project.owner)}</dd>
        <dt>当前阶段</dt><dd>${esc(project.currentStage)}</dd>
        <dt>状态</dt><dd>${esc(project.status)}</dd>
        <dt>完成率</dt><dd>${esc(project.completionRate)}%</dd>
        <dt>缺口</dt><dd>${esc(project.gapSummary)}</dd>
        <dt>下一步</dt><dd>${esc(project.nextAction)}</dd>
        <dt>截止时间</dt><dd>${esc(project.deadline || "未填写")}${project.overdue ? "（已逾期）" : ""}</dd>
        <dt>参与人员</dt><dd>${esc(project.people.join("、") || "未填写")}</dd>
        <dt>目标说明</dt><dd>${esc(project.targetSummary || "未填写")}</dd>
      </dl>
      <button class="btn" data-action="edit" data-id="${esc(project.id)}">编辑这个项目</button>
    `;
  }

  if (tab === "metrics") {
    const rows = project.metrics
      .map((metric) => {
        return `
          <tr>
            <td>${esc(metric.name)}</td>
            <td>${esc(metric.target)}</td>
            <td>${esc(metric.completed)}</td>
            <td>${esc(metric.gap)}</td>
            <td>${esc(metric.detail || "-")}</td>
          </tr>
        `;
      })
      .join("");

    els.drawerContent.innerHTML = `
      <table class="metric-table">
        <thead>
          <tr>
            <th>指标</th>
            <th>目标</th>
            <th>完成</th>
            <th>缺口</th>
            <th>说明</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  if (tab === "evidence") {
    els.drawerContent.innerHTML = `
      <dl class="kv">
        <dt>支撑材料</dt><dd>${esc(project.evidence.support || "未填写")}</dd>
        <dt>报告材料</dt><dd>${esc(project.evidence.report || "未填写")}</dd>
        <dt>PPT材料</dt><dd>${esc(project.evidence.ppt || "未填写")}</dd>
        <dt>备注</dt><dd>${esc(project.notes || "未填写")}</dd>
      </dl>
    `;
  }

  Array.from(els.drawerTabs.querySelectorAll("button")).forEach((button) => {
    button.classList.toggle("active", button.dataset.tab === tab);
  });
}

function openDrawer(projectId) {
  state.drawer.projectId = projectId;
  state.drawer.tab = "basic";
  renderDrawer();
  els.drawerMask.classList.add("open");
  els.drawerMask.setAttribute("aria-hidden", "false");
}

function closeDrawer() {
  els.drawerMask.classList.remove("open");
  els.drawerMask.setAttribute("aria-hidden", "true");
}

function setViewMode(mode) {
  state.viewMode = mode;
  els.modeTable.classList.toggle("active", mode === "table");
  els.modeCard.classList.toggle("active", mode === "card");
  els.projectTableWrap.classList.toggle("hidden", mode !== "table");
  els.projectCardList.classList.toggle("hidden", mode !== "card");
}

function renderAll() {
  const sourceName = safe(state.data.datasetName);
  els.headerMeta.textContent = `数据集：${sourceName} | 初始生成：${safe(state.data.generatedAt)} | 当前项目：${state.data.projects.length}`;
  renderTopCards();
  renderHomePanels();
  renderResultInfo();
  renderProjectTable();
  renderProjectCards();
  renderTodoList();
}

function resetFilters() {
  state.filters = {
    keyword: "",
    owner: "all",
    status: "all",
    overdue: "all",
    gap: "all"
  };

  els.keywordInput.value = "";
  els.ownerFilter.value = "all";
  els.statusFilter.value = "all";
  els.overdueFilter.value = "all";
  els.gapFilter.value = "all";
  applyFilters();
}

function exportData() {
  const payload = {
    ...state.data,
    exportedAt: new Date().toISOString()
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  const stamp = new Date().toISOString().slice(0, 19).replaceAll(":", "").replace("T", "-");
  a.href = url;
  a.download = `云南项目_v4_导出_${stamp}.json`;
  a.click();
  URL.revokeObjectURL(url);
  showToast("已导出当前数据");
}

function replaceByImport(rawText) {
  let parsed = null;
  try {
    parsed = JSON.parse(rawText);
  } catch {
    showToast("导入失败：JSON 格式不正确");
    return;
  }

  if (!confirm("导入会覆盖当前全部项目和待办，是否继续？")) {
    return;
  }
  if (!confirm("请再次确认：确定覆盖当前数据吗？")) {
    return;
  }

  state.data = normalizeData(parsed);
  saveToLocal();
  refreshFilterOptions();
  clearProjectForm();
  resetFilters();
  showToast("导入成功，数据已覆盖");
}

function restoreSeedData() {
  if (!confirm("将恢复到初始数据，当前修改会被覆盖，是否继续？")) {
    return;
  }
  if (!confirm("请再次确认：确定恢复初始数据吗？")) {
    return;
  }
  state.data = normalizeData(state.seedData);
  saveToLocal();
  refreshFilterOptions();
  clearProjectForm();
  resetFilters();
  showToast("已恢复到初始数据");
}

function bindEvents() {
  els.keywordInput.addEventListener("input", (event) => {
    state.filters.keyword = event.target.value;
    applyFilters();
  });

  els.ownerFilter.addEventListener("change", (event) => {
    state.filters.owner = event.target.value;
    applyFilters();
  });

  els.statusFilter.addEventListener("change", (event) => {
    state.filters.status = event.target.value;
    applyFilters();
  });

  els.overdueFilter.addEventListener("change", (event) => {
    state.filters.overdue = event.target.value;
    applyFilters();
  });

  els.gapFilter.addEventListener("change", (event) => {
    state.filters.gap = event.target.value;
    applyFilters();
  });

  els.resetFilterBtn.addEventListener("click", resetFilters);

  els.modeTable.addEventListener("click", () => setViewMode("table"));
  els.modeCard.addEventListener("click", () => setViewMode("card"));

  const projectActionHandler = (event) => {
    const button = event.target.closest("button[data-action]");
    if (!button) {
      return;
    }
    const action = button.dataset.action;
    const id = button.dataset.id;

    if (action === "detail") {
      openDrawer(id);
    }
    if (action === "edit") {
      closeDrawer();
      fillProjectForm(id);
    }
  };

  els.projectTableBody.addEventListener("click", projectActionHandler);
  els.projectCardList.addEventListener("click", projectActionHandler);
  els.drawerContent.addEventListener("click", projectActionHandler);

  els.todoList.addEventListener("change", (event) => {
    const input = event.target.closest("input[data-todo-id]");
    if (!input) {
      return;
    }
    const todo = state.data.todos.find((item) => item.id === input.dataset.todoId);
    if (!todo) {
      return;
    }
    todo.status = input.checked ? "done" : "todo";
    saveToLocal();
    applyFilters();
  });

  els.todoForm.addEventListener("submit", (event) => {
    event.preventDefault();
    const title = els.todoTitle.value.trim();
    if (!title) {
      return;
    }

    state.data.todos.push(
      normalizeTodo({
        id: `TODO-${Date.now()}`,
        title,
        owner: els.todoOwner.value.trim() || "待分配",
        priority: els.todoPriority.value,
        dueDate: els.todoDueDate.value,
        status: "todo",
        remark: ""
      })
    );

    saveToLocal();
    els.todoForm.reset();
    applyFilters();
    showToast("已新增待办");
  });

  els.projectForm.addEventListener("submit", (event) => {
    event.preventDefault();

    const metrics = collectMetricRows();
    const gapItems = metrics.filter((item) => item.gap > 0).map((item) => `${item.name}差${item.gap}`);

    const payload = normalizeProject({
      id: els.projectId.value || `USR-${Date.now()}`,
      sourceTable: els.projectId.value ? "manual_edit" : "manual_new",
      projectName: els.projectName.value.trim(),
      contractNo: els.contractNo.value.trim() || "待补充",
      owner: els.projectOwner.value.trim() || "待分配",
      currentStage: els.currentStage.value.trim() || "推进中",
      status: els.projectStatus.value,
      deadline: els.deadline.value.trim(),
      gapSummary: els.gapSummary.value.trim() || (gapItems.length ? gapItems.join("；") : "暂无硬性缺口"),
      nextAction: els.nextAction.value.trim() || "按计划推进并在本周更新状态",
      people: splitPeople(els.peopleText.value),
      targetSummary: els.targetSummary.value.trim(),
      evidence: {
        support: els.supportEvidence.value.trim(),
        report: "",
        ppt: ""
      },
      notes: els.notes.value.trim(),
      metrics,
      hasGap: gapItems.length > 0
    });

    if (!payload.projectName || payload.projectName === "未命名项目") {
      showToast("请先填写项目名称");
      return;
    }

    const idx = state.data.projects.findIndex((item) => item.id === payload.id);
    if (idx >= 0) {
      state.data.projects[idx] = payload;
      showToast("项目已更新");
    } else {
      state.data.projects.unshift(payload);
      showToast("项目已新增");
    }

    saveToLocal();
    refreshFilterOptions();
    applyFilters();
    clearProjectForm();
  });

  els.clearProjectBtn.addEventListener("click", clearProjectForm);

  els.exportBtn.addEventListener("click", exportData);
  els.importBtn.addEventListener("click", () => els.importInput.click());

  els.importInput.addEventListener("change", async (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) {
      return;
    }
    const text = await file.text();
    replaceByImport(text);
    els.importInput.value = "";
  });

  els.restoreBtn.addEventListener("click", restoreSeedData);

  els.drawerClose.addEventListener("click", closeDrawer);
  els.drawerMask.addEventListener("click", (event) => {
    if (event.target === els.drawerMask) {
      closeDrawer();
    }
  });

  els.drawerTabs.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-tab]");
    if (!button) {
      return;
    }
    state.drawer.tab = button.dataset.tab;
    renderDrawer();
  });

  window.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      closeDrawer();
    }
  });
}

function initViewMode() {
  if (window.innerWidth <= 760) {
    setViewMode("card");
  } else {
    setViewMode("table");
  }
}

function init(seed) {
  loadData(seed);
  clearProjectForm();
  refreshFilterOptions();
  initViewMode();
  bindEvents();
  applyFilters();
}

fetch("./data.json")
  .then((res) => res.json())
  .then((data) => init(data))
  .catch(() => {
    if (EMBEDDED_DATA && Array.isArray(EMBEDDED_DATA.projects)) {
      init(EMBEDDED_DATA);
      showToast("已使用内置数据加载");
    } else {
      els.headerMeta.textContent = "数据加载失败，请检查 data.json 是否存在。";
    }
  });
